/* 
  Client-Side Request Batching Concept
*/

// ❌ Inefficient: Making 3 separate HTTP requests
fetch('/api/users/1');
fetch('/api/users/2');
fetch('/api/users/3');

// ✅ Batching: Combining them into 1 request
fetch('/api/users/batch', {
  method: 'POST',
  body: JSON.stringify({
    ids: [1, 2, 3]
  })
});
// Server returns: [{id:1}, {id:2}, {id:3}]
